{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Integrative care, personalized programs and gentle lifestyle shifts to support balanced living in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Ailments</a>
        <a href="/approach.html">Method</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">Our Story</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="mobile-toggle" aria-expanded="false" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-body">
          <h1 class="eyebrow">Holistic support for living well</h1>
          <h2>{{TAGLINE}}</h2>
          <p class="lead">Small, sustainable shifts informed by whole-person thinking — nutrition, sleep, movement and context-focused counseling to help you feel steadier and clearer.</p>
          <div class="actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/about.html">Meet the team</a>
          </div>
        </div>
        <div class="hero-art" aria-hidden="true">
          <svg viewBox="0 0 600 360" class="art">
            <defs>
              <pattern id="p" width="100" height="100" patternUnits="userSpaceOnUse" href="assets/img/pattern.svg"></pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)" />
          </svg>
        </div>
      </div>
    </section>

    <!-- Story -->
    <section class="story wrap">
      <div class="story-inner">
        <h3>Why this approach?</h3>
        <p>We blend evidence-aware therapies with practical lifestyle coaching so you can try simpler changes that add up. Our focus is context: your routines, environment and priorities inform every suggestion.</p>
        <ul class="bullets">
          <li>Whole-day perspective — not just a single symptom</li>
          <li>Tools you can try this week</li>
          <li>Clinically informed, individualized plans</li>
        </ul>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework wrap">
      <h3>Our three-focus framework</h3>
      <div class="grid three">
        <div class="card">
          <h4>Foundations</h4>
          <p>Sleep, nourishment, movement and stress practices that reduce baseline strain.</p>
        </div>
        <div class="card">
          <h4>Context</h4>
          <p>Adjustments tailored to your routines, work and family life.</p>
        </div>
        <div class="card">
          <h4>Skills</h4>
          <p>Simple, repeatable practices for clearer decisions and steadier days.</p>
        </div>
      </div>
    </section>

    <!-- Offers (unique framing) -->
    <section class="offers wrap">
      <h3>Programs & Services</h3>
      <div class="grid two">
        <article class="service">
          <h4>Core Renewal — Starter Plan</h4>
          <p>6-week guided support focused on routines and energy management.</p>
          <div class="meta">Includes up to 3 consults + tailored plan</div>
          <div class="price">From <strong>$<span class="price-num" data-monthly="145" data-package="800">145</span></strong></div>
          <a class="btn" href="/pricing.html">See plans</a>
        </article>
        <article class="service">
          <h4>Whole Rhythm — Extended Plan</h4>
          <p>12-week program with ongoing check-ins, coaching and resources.</p>
          <div class="meta">Priority scheduling + shared resources</div>
          <div class="price">From <strong>$<span class="price-num" data-monthly="240" data-package="1400">240</span></strong></div>
          <a class="btn" href="/pricing.html">Explore</a>
        </article>
      </div>
    </section>

    <!-- Pricing comparator micro -->
    <section class="pricing-mini wrap">
      <div class="pricing-head">
        <h3>Compare monthly vs package</h3>
        <div class="toggle" role="tablist" aria-label="Pricing toggle">
          <button class="toggle-btn active" data-mode="monthly">Monthly</button>
          <button class="toggle-btn" data-mode="package">Package</button>
        </div>
      </div>
      <div class="pricing-cards grid three">
        <div class="plan">
          <h4>Essentials</h4>
          <div class="amount">$<span class="anim" data-monthly="75" data-package="420">75</span></div>
          <div class="label">Per month / or package</div>
        </div>
        <div class="plan featured">
          <h4>Stability</h4>
          <div class="amount">$<span class="anim" data-monthly="145" data-package="800">145</span></div>
          <div class="label">Per month / or package</div>
        </div>
        <div class="plan">
          <h4>Renewal</h4>
          <div class="amount">$<span class="anim" data-monthly="240" data-package="1400">240</span></div>
          <div class="label">Per month / or package</div>
        </div>
      </div>
      <p class="note">Educational pricing examples for planning. Actual plans include clinical review and personalized recommendations.</p>
    </section>

    <!-- Testimonials / Proof Gallery -->
    <section class="proof wrap">
      <h3>What people notice</h3>
      <div class="proof-inner">
        <div class="gallery" aria-live="polite">
          <div class="slide active" data-index="0">
            <blockquote>"I sleep more consistently and have clearer mornings. Small steps, big difference."</blockquote>
            <cite>— A client in {{CITY}}</cite>
          </div>
          <div class="slide" data-index="1">
            <blockquote>"The team helped me reframe my workday and I feel less overwhelmed."</blockquote>
            <cite>— Parent & teacher</cite>
          </div>
          <div class="slide" data-index="2">
            <blockquote>"Practical, compassionate coaching that respected my life context."</blockquote>
            <cite>— Office professional</cite>
          </div>
        </div>

        <aside class="cred">
          <div class="badges">
            <div class="badge" data-tip="Board-certified clinicians and nutritionists">MD & RDN</div>
            <div class="badge" data-tip="Published case reports and community workshops">Community work</div>
            <div class="badge" data-tip="Secure telehealth and confidential records">Secure care</div>
          </div>
          <div class="thumbs">
            <button class="thumb active" data-index="0" aria-label="Testimonial 1"></button>
            <button class="thumb" data-index="1" aria-label="Testimonial 2"></button>
            <button class="thumb" data-index="2" aria-label="Testimonial 3"></button>
          </div>
        </aside>
      </div>
    </section>

    <!-- CTA strip -->
    <section class="cta-strip">
      <div class="wrap cta-inner">
        <div>
          <h4>Ready to schedule a brief consult?</h4>
          <p>Start with a short call to see if our style fits your needs — we’ll offer clear options and next steps.</p>
        </div>
        <div class="actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Contact</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}} · <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <nav>
        <a href="/services.html">Offerings</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">Our Story</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <div>
        <p>Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
