{"path":"assets/css/styles.css","content":"/* Base styles for holistic_medicine - bold_playful / warm_storyteller */
:root{
  --bg:#fff8f2;--muted:#6b5b4c;--accent:#7fa28b;--accent-2:#f08a5d;--card:#fff;--glass:rgba(255,255,255,0.6);
  --max-width:1100px;--radius:12px;--accent-3:#ffd166;
}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:var(--muted);background:var(--bg);margin:0}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(90deg,#fff 0%, #fff9f2 100%);border-bottom:1px solid #f0e6df}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:#2f2a27;text-decoration:none;font-size:1.15rem}
.main-nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:0.5rem 0.8rem;border-radius:8px;margin-left:1rem}
.mobile-toggle{display:none}
.hero{padding:3rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:2rem;align-items:center}
.eyebrow{color:var(--accent-2);font-weight:700;margin:0}
.hero h2{font-size:2rem;margin:0.35rem 0 1rem;color:#2b2b2b}
.lead{color:#54463e}
.actions{margin-top:1rem}
.btn{display:inline-block;padding:0.6rem 1rem;border-radius:10px;text-decoration:none;color:var(--muted);border:1px solid rgba(0,0,0,0.06);background:var(--card);}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.hero-art .art{width:100%;height:240px;border-radius:12px;box-shadow:0 6px 18px rgba(0,0,0,0.06)}
.story{background:linear-gradient(180deg, rgba(127,162,139,0.06), transparent);padding:2rem;border-radius:10px}
.bullets{display:flex;gap:1rem;list-style:none;padding:0;margin:1rem 0 0}
.bullets li{background:var(--card);padding:0.6rem 0.9rem;border-radius:8px}
.framework .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.card{background:var(--card);padding:1rem;border-radius:10px}
.offers .grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.service{background:var(--card);padding:1rem;border-radius:10px}
.service .price{margin-top:0.5rem}
.pricing-mini{margin-top:1.5rem;padding:1rem;background:rgba(255,255,255,0.6);border-radius:10px}
.pricing-head{display:flex;align-items:center;justify-content:space-between}
.toggle{background:#fff;padding:4px;border-radius:999px;display:inline-flex}
.toggle-btn{padding:6px 12px;border-radius:999px;border:none;background:transparent;cursor:pointer}
.toggle-btn.active{background:var(--accent);color:#fff}
.pricing-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.plan{background:linear-gradient(180deg,#fff,#fff9f2);padding:1rem;border-radius:10px;text-align:center}
.plan.featured{box-shadow:0 6px 18px rgba(160,140,120,0.12);transform:translateY(-6px);}
.amount{font-size:1.6rem;font-weight:700;color:#2d2d2d}
.note{font-size:0.9rem;color:#6b5b4c;margin-top:0.75rem}
.proof{margin-top:1.5rem}
.proof-inner{display:flex;gap:1rem;align-items:flex-start}
.gallery{flex:1;background:var(--card);padding:1rem;border-radius:10px;min-height:130px;position:relative}
.slide{display:none}
.slide.active{display:block}
.slide blockquote{margin:0;font-size:1.05rem;color:#2a2a2a}
.cite{display:block;margin-top:0.6rem;color:#7b6a60}
.cred{width:240px}
.badges{display:flex;gap:0.5rem;flex-wrap:wrap}
.badge{background:var(--glass);padding:0.4rem 0.6rem;border-radius:8px;font-weight:600;cursor:default}
.badge[data-tip]:hover{position:relative}
.badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:0;bottom:calc(100% + 8px);background:#2b2b2b;color:#fff;padding:6px 8px;border-radius:6px;font-size:0.8rem;white-space:nowrap}
.thumbs{margin-top:1rem;display:flex;gap:0.5rem}
.thumb{width:14px;height:14px;border-radius:50%;background:#e7e1d9;border:none}
.thumb.active{background:var(--accent)}
.cta-strip{background:linear-gradient(90deg,#fef6ef,#fff);padding:1rem;margin-top:1.5rem;border-radius:10px}
.site-footer{border-top:1px solid #f0e6df;padding:1.5rem 0;margin-top:2rem}
.footer-grid{display:grid;grid-template-columns:1fr auto 1fr;gap:1rem;align-items:center}
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .framework .grid{grid-template-columns:1fr}
  .offers .grid{grid-template-columns:1fr}
  .pricing-cards{grid-template-columns:1fr}
  .proof-inner{flex-direction:column}
  .footer-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .mobile-toggle{display:inline-block}
}
/* small utility */
.text-muted{color:#8b7b6e}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Pricing comparator: toggle and animate numbers
  function animateNumber(el, start, end, duration){
    var startTime=null; var diff=end-start;
    function step(ts){
      if(!startTime) startTime=ts;
      var progress=Math.min((ts-startTime)/duration,1);
      var value=Math.round(start + diff * easeOutCubic(progress));
      el.textContent = value;
      if(progress<1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  function easeOutCubic(t){ return (--t)*t*t+1 }

  var toggleBtns = document.querySelectorAll('.toggle-btn');
  var animEls = document.querySelectorAll('.anim, .price-num');
  var currentMode = 'monthly';

  function setMode(mode){
    currentMode = mode;
    toggleBtns.forEach(function(b){b.classList.toggle('active', b.dataset.mode===mode)});
    animEls.forEach(function(el){
      var from = parseInt(el.textContent,10) || 0;
      var to = parseInt(el.dataset[mode],10) || 0;
      animateNumber(el, from, to, 500);
    });
  }
  toggleBtns.forEach(function(btn){
    btn.addEventListener('click', function(){ setMode(this.dataset.mode); });
  });

  // Initialize with monthly mode after DOM ready
  document.addEventListener('DOMContentLoaded', function(){
    setMode('monthly');
  });

  // Proof Gallery rotation
  var gallery = document.querySelector('.gallery');
  if(gallery){
    var slides = gallery.querySelectorAll('.slide');
    var thumbs = document.querySelectorAll('.thumb');
    var index = 0; var interval = 6000; var rot;
    function show(i){
      slides.forEach(function(s){ s.classList.toggle('active', +s.dataset.index===i); });
      thumbs.forEach(function(t){ t.classList.toggle('active', +t.dataset.index===i); });
      index = i;
    }
    function next(){ show((index+1) % slides.length); }
    thumbs.forEach(function(t){ t.addEventListener('click', function(){ clearInterval(rot); show(+this.dataset.index); rot=setInterval(next, interval); }); });
    rot = setInterval(next, interval);
  }

  // Mobile nav toggle
  var mobileToggle = document.querySelector('.mobile-toggle');
  var mainNav = document.querySelector('.main-nav');
  if(mobileToggle && mainNav){
    mobileToggle.addEventListener('click', function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      mainNav.style.display = expanded ? 'none' : 'flex';
    });
  }

  // Simple deep-link CTA handler (ensures placeholders still work if configured)
  var ctas = document.querySelectorAll('a[href^="{{PRIMARY_CTA_URL}}"]');
  // No-op: placeholder present in HTML until templated

})();"} 
